import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/adlanding.css';

const RED_FLAGS = [
  'Urgency and scarcity — "before it expires", "first 50 students" push you to act fast without thinking.',
  'A reward that is disproportionate to any action you took ("You\'ve won...") for something you never entered.',
  'A generic "Sponsored" ad sitting inside a page that is not the actual rewards or verification site.',
  'A vague call to action ("Claim Now", "Verify Account") instead of a named, specific process.',
];

export default function AdLanding() {
  const navigate = useNavigate();

  return (
    <div className="adland-page">
      <div className="adland-card">
        <span className="adland-badge">Simulation Checkpoint</span>
        <h1>That ad was part of the exercise.</h1>
        <p className="adland-intro">
          No data was collected and nothing was sent anywhere — clicking it just brought you here.
          In a real attack, a banner like this is designed to get you to click without stopping to think.
        </p>

        <h2>What tipped it off</h2>
        <ul className="adland-flags">
          {RED_FLAGS.map((flag) => (
            <li key={flag}>{flag}</li>
          ))}
        </ul>

        <h2>If this were real</h2>
        <p>
          A genuine version of this ad would usually lead to a lookalike login or payment page built to
          capture your credentials or card details. The safest response is to close the tab, navigate to
          the real site directly instead of clicking through, and report the ad if the platform allows it.
        </p>

        <button type="button" className="adland-btn" onClick={() => navigate(-1)}>
          ← Back to where you were
        </button>
      </div>
    </div>
  );
}
